function sum(nums) {
  let total = 0;
  for (const n of nums) total += n;
  return total;
}

function fizzbuzz(n) {
  const out = [];
  for (let i = 1; i <= n; i++) {
    if (i % 15 === 0) out.push("FizzBuzz");
    else if (i % 3 === 0) out.push("Fizz");
    else if (i % 5 === 0) out.push("Buzz");
    else out.push(i);
  }
  return out;
}

function max(nums) {
  let best = nums[0];
  for (const n of nums) {
    if (n > best) best = n;
  }
  return best;
}
